11	export class FakeElement {
12	  constructor(tagName, id = '') {
13	    this.tagName = tagName;
14	    this.id = id;
15	    this.children = [];
16	    this.value = '';
17	    this.type = '';
18	    this.disabled = false;
19	    this.listeners = new Map();
20	  }
21	
22	  get textContent() {
23	    return this.children.map((c) => c.textContent).join('');
24	  }
25	
26	  set textContent(s) {
27	    this.children = s === '' ? [] : [toNode(String(s))];
28	  }
29	
30	  append(...nodes) {
31	    this.children = [...this.children, ...nodes.map(toNode)];
32	  }
33	
34	  replaceChildren(...nodes) {
35	    this.children = nodes.map(toNode);
36	  }
37	
38	  addEventListener(type, fn) {
39	    this.listeners.set(type, [...(this.listeners.get(type) ?? []), fn]);
40	  }
41	
42	  dispatch(type) {
43	    const event = { preventDefault() { this.defaultPrevented = true; }, defaultPrevented: false };
44	    for (const fn of this.listeners.get(type) ?? []) fn(event);
45	    return event;
46	  }
47	}
